import sys

def main():
    N = int(sys.stdin.readline())
    dp = [0] * (N + 1)

    for i in range(1, N + 1):
        x = i
        best = 10**9

        while x > 0:
            d = x % 10
            x //= 10
            if d > 0:
                best = min(best, dp[i - d] + 1)

        dp[i] = best

    print(dp[N])

if __name__ == "__main__":
    main()
